WITH scored AS (SELECT id, store_id, sale_date, SUM(units) OVER w_ordered running_units, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY sale_date, id) row_seq, COUNT(revenue) OVER w_ordered_2 store_id_count_revenue FROM store_sales WHERE revenue IS NOT NULL WINDOW w_ordered AS (PARTITION BY store_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered_2 AS (PARTITION BY store_id)), enriched AS (SELECT id, store_id, sale_date, running_units, MIN(running_units) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_min_running_units, MAX(running_units) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_max_running_units, AVG(running_units) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_avg_running_units, AVG(running_units) OVER (ORDER BY store_id_count_revenue, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) running_units_avg_5 FROM scored), enriched_store_sales AS (SELECT a.*, s.region, s.opened_date FROM enriched a LEFT JOIN stores s ON a.store_id = s.id), joined AS (SELECT s.id, s.store_id, s.sale_date, s.last3_min_running_units, s.last3_max_running_units, s.last3_avg_running_units, s.running_units_avg_5, s.opened_date, p.sqft FROM enriched_store_sales s JOIN stores p ON s.store_id = p.id), enriched_store_sales_2 AS (SELECT id, store_id, sale_date, last3_min_running_units, running_units_avg_5, opened_date, sqft, FIRST_VALUE(last3_min_running_units) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY running_units_avg_5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_last3_min_running_units, ROUND(last3_max_running_units / SUM(last3_max_running_units) OVER (PARTITION BY store_id), 4) last3_max_running_units_share, LEAD(running_units_avg_5, 2) OVER (ORDER BY last3_min_running_units, id) next_running_units_avg_5 FROM joined) SELECT id, sale_date, last3_min_running_units, running_units_avg_5, sqft, first_known_last3_min_running_units, last3_max_running_units_share FROM enriched_store_sales_2;
